use std::ffi::c_void;
use inkwell::{builder::Builder,context::Context,module::Module,types::BasicTypeEnum,values::{BasicValueEnum,FunctionValue,PointerValue}};
use crate::{expr::Expr,types::TypeInfo};
pub(crate) struct Lowering{pub(crate) module:*const c_void}
pub(crate) enum LoweredValue<'ctx>{Value(BasicValueEnum<'ctx>),Pointer{pointer:PointerValue<'ctx>,type_info:TypeInfo}}
mod binary;mod cast;mod control;mod field;mod constant;mod intrinsic;mod materialize;mod unary;mod tuple;
impl Lowering{
 pub(crate) fn new<'ctx>(module:&Module<'ctx>)->Self{Self{module:module as *const Module<'ctx> as *const c_void}}
 pub(crate) fn module<'ctx>(&self)->&'ctx Module<'ctx>{unsafe{&*(self.module as *const Module<'ctx>)}}
 fn emit_bounds_check<'ctx>(&self,context:&'ctx Context,builder:&Builder<'ctx>,function:FunctionValue<'ctx>,index:inkwell::values::IntValue<'ctx>,length:inkwell::values::IntValue<'ctx>)->Result<(),String>{let in_bounds=builder.build_int_compare(inkwell::IntPredicate::ULT,index,length,"index_in_bounds").map_err(|e|format!("failed to build bounds comparison: {:?}",e))?;let ok_block=context.append_basic_block(function,"index_in_bounds");let trap_block=context.append_basic_block(function,"index_oob");builder.build_conditional_branch(in_bounds,ok_block,trap_block).map_err(|e|format!("failed to build bounds branch: {:?}",e))?;builder.position_at_end(trap_block);let trap_type=context.void_type().fn_type(&[],false);let module=self.module();let trap=module.get_function("llvm.trap").unwrap_or_else(||module.add_function("llvm.trap",trap_type,None));builder.build_call(trap,&[],"bounds_trap").map_err(|e|format!("failed to emit bounds trap: {:?}",e))?;builder.build_unreachable().map_err(|e|format!("failed to terminate bounds trap block: {:?}",e))?;builder.position_at_end(ok_block);Ok(())}
 pub(crate) fn lower_expr<'ctx>(&self,context:&'ctx Context,builder:&Builder<'ctx>,function:FunctionValue<'ctx>,arguments:&[PointerValue<'ctx>],argument_types:&[TypeInfo],expected_type:&TypeInfo,expr:&Expr)->Result<LoweredValue<'ctx>,String>{match expr{
 Expr::Argument(index)=>{let pointer=*arguments.get(*index).ok_or_else(||format!("argument index {} out of bounds",index))?;let type_info=argument_types.get(*index).cloned().ok_or_else(||format!("argument type index {} out of bounds",index))?;Ok(LoweredValue::Pointer{pointer,type_info})},
 Expr::Constant(value)=>self.lower_constant(context,value),
 Expr::Cast{expr,source_type,target_type}=>cast::lower_cast(self,context,builder,function,arguments,argument_types,source_type,target_type,expr),
 Expr::Index{sequence,index}=>{let base=self.lower_expr(context,builder,function,arguments,argument_types,expected_type,sequence)?;let (pointer,sequence_info,element_info)=match base{LoweredValue::Pointer{pointer,type_info}=>{let element=type_info.indexed_element_type().cloned().ok_or_else(||"indexing requires an indexable sequence".to_string())?;(pointer,type_info,element)},LoweredValue::Value(_)=>return Err("indexing requires an addressable sequence".into())};let idx=self.lower_expr(context,builder,function,arguments,argument_types,&TypeInfo::Usize,index)?;let idx=self.materialize_value(context,builder,idx)?;let idx=match idx{BasicValueEnum::IntValue(v)=>v,_=>return Err("sequence index must be an integer".into())};let p=match &sequence_info{TypeInfo::Array{length,..}=>{self.emit_bounds_check(context,builder,function,idx,context.i64_type().const_int(*length as u64,false))?;let sequence_type=crate::compiler::llvm_type(context,&sequence_info)?;unsafe{builder.build_gep(sequence_type,pointer,&[context.i32_type().const_zero(),idx],"array_index")}.map_err(|e|format!("failed to build array index GEP: {:?}",e))?},TypeInfo::Slice{..}=>{let slice_type=crate::compiler::llvm_type(context,&sequence_info)?;let data_field=builder.build_struct_gep(slice_type.into_struct_type(),pointer,0,"slice_data").map_err(|e|format!("failed to access slice data pointer: {:?}",e))?;let len_field=builder.build_struct_gep(slice_type.into_struct_type(),pointer,1,"slice_len").map_err(|e|format!("failed to access slice length: {:?}",e))?;let len=builder.build_load(context.i64_type(),len_field,"slice_len_value").map_err(|e|format!("failed to load slice length: {:?}",e))?.into_int_value();self.emit_bounds_check(context,builder,function,idx,len)?;let data=builder.build_load(context.ptr_type(inkwell::AddressSpace::default()),data_field,"slice_data_value").map_err(|e|format!("failed to load slice data pointer: {:?}",e))?.into_pointer_value();let element_type=crate::compiler::llvm_type(context,&element_info)?;unsafe{builder.build_gep(element_type,data,&[idx],"slice_index")}.map_err(|e|format!("failed to build slice index GEP: {:?}",e))?},_=>return Err("indexing requires an indexable sequence".into())};Ok(LoweredValue::Pointer{pointer:p,type_info:element_info})},
 Expr::Field{object,name}=>self.lower_field(context,builder,function,arguments,argument_types,expected_type,object,name),Expr::Tuple{elements}=>self.lower_tuple(context,builder,function,arguments,argument_types,expected_type,elements),Expr::Intrinsic{intrinsic,arguments:a}=>self.lower_intrinsic(context,builder,function,arguments,argument_types,expected_type,*intrinsic,a),Expr::IfElse{condition,then_branch,else_branch}=>self.lower_if_else(context,builder,function,arguments,argument_types,expected_type,condition,then_branch,else_branch),Expr::Add{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Add),Expr::Sub{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Sub),Expr::Mul{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Mul),Expr::Div{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Div),Expr::Rem{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Rem),Expr::Eq{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Eq),Expr::Ne{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Ne),Expr::Lt{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Lt),Expr::Le{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Le),Expr::Gt{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Gt),Expr::Ge{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Ge),Expr::And{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::And),Expr::Or{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Or),Expr::BitAnd{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::BitAnd),Expr::BitOr{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::BitOr),Expr::BitXor{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::BitXor),Expr::Shl{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Shl),Expr::Shr{lhs,rhs}=>self.lower_binary(context,builder,function,arguments,argument_types,expected_type,lhs,rhs,crate::operators::BinaryOp::Shr),Expr::Not{operand}=>self.lower_unary(context,builder,function,arguments,argument_types,expected_type,operand,crate::operators::UnaryOp::Not),Expr::Neg{operand}=>self.lower_unary(context,builder,function,arguments,argument_types,expected_type,operand,crate::operators::UnaryOp::Neg)}}
 pub(crate) fn llvm_struct_type<'ctx>(context:&'ctx Context,type_info:&TypeInfo)->Result<inkwell::types::StructType<'ctx>,String>{match crate::compiler::llvm_type(context,type_info)?{BasicTypeEnum::StructType(value)=>Ok(value),_=>Err("expected struct LLVM type".to_string())}}
}
